@Service
public class PaymentService {

    @Transactional                                          // REQUIRED
    public void pay(Order order) {
        logAudit("payment started");
        charge(order);                                      // may throw
    }

    @Transactional(propagation = Propagation.REQUIRES_NEW)
    public void logAudit(String message) {
        auditRepo.insert(message);
    }
}

// OrderService
@Transactional                        // REQUIRED
public void checkout(Order order) {
    orderRepo.save(order);            // write 1
    audit.log("checkout");            // AuditService, REQUIRES_NEW
    try {
        stock.reserve(order);         // StockService, REQUIRED, throws
    } catch (RuntimeException e) {
        // swallowed
    }
}

